             { id: "sql", label: "SQL", note: "Queries relational databases.", correct: false }
           ]
         }
       ];

       function QuizOption({ questionId, answer }) {
         const inputId = `${questionId}-${answer.id}`;

         return `
           <label class="option" for="${inputId}">
             <input id="${inputId}" type="checkbox" name="${questionId}" value="${answer.id}">
             <span class="option-text">
               <span class="option-label">${answer.label}</span>
               <span class="option-note">${answer.note}</span>
             </span>
           </label>
         `;
       }

       function QuizQuestion({ question, index }) {
         const helpId = `${question.id}-help`;
         const describedBy = question.help ? ` aria-describedby="${helpId}"` : "";
         const helpText = question.help ? `<p class="help-text" id="${helpId}">${question.help}</p>` : "";

         return `
           <div class="form-field">
             <fieldset${describedBy}>
               <legend>${index + 1}. ${question.prompt}</legend>
               ${helpText}
               <div class="options">
                 ${question.answers.map((answer) => QuizOption({ questionId: question.id, answer })).join("")}
