         const result = document.querySelector("#quiz-result");
         const unanswered = quizQuestions.find((question) => getSelectedValues(form, question.id).length === 0);

         if (unanswered) {
           result.textContent = "Error: Answer every question before checking your score.";
           result.dataset.state = "error";
           form.querySelector(`input[name="${unanswered.id}"]`).focus();
           return;
         }

         const score = quizQuestions.reduce((total, question) => {
           const selected = getSelectedValues(form, question.id);
           const correct = question.answers.filter((answer) => answer.correct).map((answer) => answer.id);
           return total + (arraysMatch(selected, correct) ? 1 : 0);
         }, 0);

         result.textContent = `You scored ${score} out of ${quizQuestions.length}.`;
         result.dataset.state = score === quizQuestions.length ? "success" : "";
       });
     </script>
