  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content">
      <div class="quiz-shell">
        <header class="hero">
          <p class="eyebrow">Multiple-answer quiz</p>
          <h1>Computer Languages</h1>
          <p class="intro">
            Choose all answers that apply for each question, then submit your selections.
          </p>
        </header>

        <form id="quiz-form" novalidate>
          <div id="quiz-root"></div>
          <div class="actions">
            <button type="submit">Check answers</button>
            <p class="result" id="quiz-result" aria-live="polite"></p>
          </div>
        </form>
      </div>
    </main>

    <script>
      const quizQuestions = [
        {
          id: "language-types",
          prompt: "Which of these are programming languages?",
          help: "Select every option that is commonly used to write software.",
          answers: [
            { id: "python", label: "Python", note: "Popular for scripting, web apps, and data science.", correct: true },
            { id: "javascript", label: "JavaScript", note: "Runs in browsers and many server environments.", correct: true },
            { id: "html", label: "HTML", note: "A markup language for structuring web content.", correct: false },
            { id: "ruby", label: "Ruby", note: "Known for expressive syntax and web frameworks.", correct: true }
          ]
        },
        {
          id: "compiled-languages",
          prompt: "Which languages are commonly compiled before running?",
          answers: [
            { id: "c", label: "C", note: "Typically compiled to native machine code.", correct: true },
            { id: "rust", label: "Rust", note: "Compiled with strong memory-safety guarantees.", correct: true },
            { id: "typescript", label: "TypeScript", note: "Transpiled to JavaScript before execution.", correct: true },
            { id: "css", label: "CSS", note: "A stylesheet language interpreted by browsers.", correct: false }
          ]
        },
        {
          id: "web-languages",
          prompt: "Which languages are core technologies for building web pages?",
          answers: [
            { id: "html", label: "HTML", note: "Defines document structure and semantics.", correct: true },
            { id: "css", label: "CSS", note: "Controls presentation and layout.", correct: true },
            { id: "javascript", label: "JavaScript", note: "Adds behavior and interactivity.", correct: true },
            { id: "sql", label: "SQL", note: "Queries relational databases.", correct: false }
          ]
        }
      ];

      function QuizOption({ questionId, answer }) {
        const inputId = `${questionId}-${answer.id}`;

        return `
          <label class="option" for="${inputId}">
            <input id="${inputId}" type="checkbox" name="${questionId}" value="${answer.id}">
            <span class="option-text">
              <span class="option-label">${answer.label}</span>
              <span class="option-note">${answer.note}</span>
            </span>
          </label>
        `;
      }

      function QuizQuestion({ question, index }) {
        const helpId = `${question.id}-help`;
        const errorId = `${question.id}-error`;
        const descriptionIds = [question.help ? helpId : "", errorId].filter(Boolean).join(" ");
        const describedBy = ` aria-describedby="${descriptionIds}"`;
        const helpText = question.help ? `<p class="help-text" id="${helpId}">${question.help}</p>` : "";

        return `
          <div class="form-field">
            <fieldset${describedBy}>
              <legend>${index + 1}. ${question.prompt}</legend>
              ${helpText}
              <div class="options">
                ${question.answers.map((answer) => QuizOption({ questionId: question.id, answer })).join("")}
              </div>
              <p class="field-error" id="${errorId}" hidden>Error: Select at least one answer for this question.</p>
            </fieldset>
          </div>
        `;
      }

      function QuizApp({ questions }) {
        return questions.map((question, index) => QuizQuestion({ question, index })).join("");
      }

      function getSelectedValues(form, questionId) {
        return Array.from(form.querySelectorAll(`input[name="${questionId}"]:checked`)).map(
          (input) => input.value
        );
      }

      function arraysMatch(a, b) {
        return a.length === b.length && a.every((value) => b.includes(value));
      }

      document.querySelector("#quiz-root").innerHTML = QuizApp({ questions: quizQuestions });

      document.querySelector("#quiz-form").addEventListener("submit", (event) => {
        event.preventDefault();

        const form = event.currentTarget;
        const result = document.querySelector("#quiz-result");
        quizQuestions.forEach((question) => {
          document.querySelector(`#${question.id}-error`).hidden = true;
        });
        const unanswered = quizQuestions.find((question) => getSelectedValues(form, question.id).length === 0);

        if (unanswered) {
          document.querySelector(`#${unanswered.id}-error`).hidden = false;
          result.textContent = "Error: Answer every question before checking your score.";
          result.dataset.state = "error";
          form.querySelector(`input[name="${unanswered.id}"]`).focus();
          return;
        }

        const score = quizQuestions.reduce((total, question) => {
          const selected = getSelectedValues(form, question.id);
          const correct = question.answers.filter((answer) => answer.correct).map((answer) => answer.id);
          return total + (arraysMatch(selected, correct) ? 1 : 0);
        }, 0);

        result.textContent = `You scored ${score} out of ${quizQuestions.length}.`;
        result.dataset.state = score === quizQuestions.length ? "success" : "";
      });
    </script>
  </body>
</html>
