          id: "web-languages",
          prompt: "Which languages are core technologies for building web pages?",
          answers: [
            { id: "html", label: "HTML", note: "Defines document structure and semantics.", correct: true },
            { id: "css", label: "CSS", note: "Controls presentation and layout.", correct: true },
            { id: "javascript", label: "JavaScript", note: "Adds behavior and interactivity.", correct: true },
